import type { ReactNode } from 'react';

import sheinLogo from '@/images/marketplaces/shein.png';

/**
 * Official marketplace marks.
 *
 * Two shapes are accepted, because the brands do not all publish the same
 * thing. Either way the artwork carries no colour of its own — it is drawn in
 * the tile's text colour, which `MARKETPLACE_COLORS` below sets per brand:
 *
 * - **Inline SVG** — the good case. Paths use `fill="currentColor"`.
 * - **A monochrome image with a transparent background** — drawn as a CSS mask
 *   rather than an `<img>`, so the artwork's own colour is discarded and only
 *   its silhouette is painted. A full-colour logo cannot go through here.
 *
 * Marks keep a fixed height and derive their width from the artwork's own
 * proportions. A marketplace missing from this map falls back to its name set
 * as a wordmark, so the map can be filled in one brand at a time.
 */

/**
 * Paint a transparent monochrome image in the current text colour.
 *
 * @param ratio the artwork's width divided by its height, which sets the width
 *              the mark takes at the height the marquee gives it.
 */
function maskedLogo(source: string, ratio: number, label: string): ReactNode {
    return (
        <span
            role="img"
            aria-label={label}
            className="block h-3.5 bg-current"
            style={{
                aspectRatio: ratio,
                maskImage: `url(${source})`,
                maskSize: 'contain',
                maskRepeat: 'no-repeat',
                maskPosition: 'center',
            }}
        />
    );
}

